"""Registry of distinct, auditable trading-research specialist archetypes.

These are methodology-specific research roles, not simulated real people or claims
of profitability. Agents must cite evidence, identify counter-evidence, and abstain
when information is insufficient.
"""
from dataclasses import dataclass

@dataclass(frozen=True)
class ExpertProfile:
    agent_id: str
    name: str
    specialty: str
    method_checklist: tuple[str, ...]
    failure_modes: tuple[str, ...]
    search_topics: tuple[str, ...]
    source_topics: tuple[str, ...] = ("quant",)

def _p(agent_id, name, specialty, checks, risks, searches, routes=("quant",)):
    return ExpertProfile(agent_id, name, specialty, tuple(checks), tuple(risks), tuple(searches), tuple(routes))

